import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"The IR gains pipeline(depth), and the schedule programme stops there","description":"","frontmatter":{"title":"The IR gains `pipeline(depth)`, and the schedule programme stops there","type":"adr","date":"2026-10-29T00:00:00.000Z","status":"implemented","applies_to":"`lib-kernel-ir` (op 10), `compile-triton` (num_stages), `graphopt` (P24)"},"headers":[],"relativePath":"handl/project/adrs/0166-pipeline-depth-and-the-end-of-the-schedule-programme.md","filePath":"vendored/handl/project/adrs/0166-pipeline-depth-and-the-end-of-the-schedule-programme.md"}'),a={name:`handl/project/adrs/0166-pipeline-depth-and-the-end-of-the-schedule-programme.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0166-the-ir-gains-pipeline-depth-and-the-schedule-programme-stops-there" tabindex="-1">ADR-0166: The IR gains <code>pipeline(depth)</code>, and the schedule programme stops there <a class="header-anchor" href="#adr-0166-the-ir-gains-pipeline-depth-and-the-schedule-programme-stops-there" aria-label="Permalink to “ADR-0166: The IR gains pipeline(depth), and the schedule programme stops there”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><code>pipeline(depth)</code> is the <strong>tenth op</strong>. It denotes the <strong>identity</strong> and lowers to Triton&#39;s <code>num_stages</code>. A schedule changes when bytes arrive, never which bytes — so all <code>split_k</code> variants remain provably equal.</li><li>It is priced at <strong>zero</strong> (no extra traffic, no launch). The cost model is a lower bound and must not pretend to know whether overlap happened.</li><li><code>stage_shared</code> is <strong>not</strong> added. <code>num_stages</code> already stages loads through shared memory, and a second annotation with no separate effect is decoration.</li><li><strong>The schedule-vocabulary programme is closed.</strong> Measured: depth 1 → 4 moves <code>down_proj</code> 52.5 → 52.1 µs and <code>gate_proj</code> 52.4 → 52.1 µs — 0.4–0.8 %, inside run-to-run noise. No further schedule ops.</li><li>The 47 % → 86 % gap to Marlin is therefore <strong>not load latency</strong>. It is the unpack/<code>dot</code> arithmetic, and it is not reachable by annotating this kernel shape.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0165&#39;s review said a data-only IR &quot;can only express naive schedules, which will lose to the hand kernel every time&quot;. That was a prediction about latency hiding, and it was cheap to test: the most likely lever was <code>num_stages</code> on the k-loop of a memory-bound GEMV. It does nothing. Two readings were possible — the vocabulary is inadequate, or the schedule was never the bottleneck — and the measurement picks the second. Recording it stops the next session from re-running the same sweep, and stops the pitch from promising a schedule compiler the hardware does not reward here.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>More schedule ops</strong> (<code>stage_shared</code>, pipelining combinators) — each would need its own measured effect, and the first one is zero.</li><li><strong>A <code>pipeline</code> that changes meaning</strong> — it would break the property that all <code>split_k</code> terms denote one function, which is the IR&#39;s only proof.</li><li><strong>Deleting <code>pipeline</code></strong> — it is the instrument that produced the negative result; the finding is not reproducible without it.</li><li><strong>Claiming the IR is a compiler</strong> — it is a config-search substrate with a faithful lowering, and <code>pitch</code> wording should say so.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>lib-kernel-ir/src/lib_kernel_ir/ops.py</code> — <code>pipeline</code> present; <code>OPS</code> is 10.</li><li><code>lib-kernel-ir/tests/test_ops.py</code> — denotes the identity, cost unchanged, depth &lt; 1 refused.</li><li><code>compile-triton/src/{term,codegen}.rs</code> — depth read from the term, emitted as <code>num_stages=PIPELINE_DEPTH</code>; cargo tests assert both.</li><li><code>graphopt/docs/reports/p24_m2_schedule.json</code> — the 48-cell sweep.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};